#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W for (i=0;i<tmp;i++)

int i;
int radix = 255;
long range_val = 1;
long low_val = 0;
int tmp;
int cc[200000];

unsigned char output_buf[100000];
int output_pos = 0;

void emit_byte(int b) {
    output_buf[output_pos++] = (unsigned char)b;
}

void put_bit(int bit, int ctx) {
    // Emit bytes if range gets too small
    while (range_val < radix) {
        emit_byte((low_val / range_val) % radix + 1);
        low_val = low_val % range_val;
        range_val *= radix;
    }

    int *counts = cc + ctx * 2;
    long split = range_val * (counts[0] + 1) / (counts[0] + counts[1] + 2);

    if (bit) {
        low_val += split;
        range_val -= split;
    } else {
        range_val = split;
    }

    counts[bit]++;
}

void put_integer(int value, int size_bits, int ctx) {
    int subtract_it = 1 << size_bits;
    value += subtract_it;

    // Find number of bits needed
    int nbits = 0;
    int temp = value;
    while (temp > 0) {
        nbits++;
        temp >>= 1;
    }

    ctx *= 99;
    // Emit unary: nbits zeros then a one
    for (i = 0; i < nbits; i++) {
        put_bit(0, size_bits + 1 + i + ctx);
    }
    put_bit(1, size_bits + 1 + nbits + ctx);

    // Emit the value in binary
    for (i = nbits - 1; i >= 0; i--) {
        put_bit((value >> i) & 1, ctx);
    }
}

void flush_encoder() {
    for (i = 0; i < 10; i++) {
        emit_byte((low_val / range_val) % radix + 1);
    }
}

void find_match(unsigned char *data, int pos, int len, int *best_offset, int *best_len) {
    *best_len = 0;
    *best_offset = 0;
    int max_offset = 31;
    int max_length = 3;

    for (int offset = 1; offset <= max_offset && offset <= pos; offset++) {
        int match_len = 0;
        while (match_len < max_length && 
               pos + match_len < len &&
               data[pos - offset + match_len] == data[pos + match_len]) {
            match_len++;
        }

        if (match_len > *best_len) {
            *best_len = match_len;
            *best_offset = offset;
        }
    }
}

int main() {
    FILE *f = fopen("/app/data.txt", "r");
    if (!f) {
        fprintf(stderr, "Cannot open data.txt\n");
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long file_size = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *data = malloc(file_size + 1);
    fread(data, 1, file_size, f);
    fclose(f);

    // Build operations
    int *ops = malloc(file_size * 3 * sizeof(int));
    int num_ops = 0;
    int pos = 0;

    while (pos < file_size) {
        int offset, length;
        find_match(data, pos, file_size, &offset, &length);

        if (length >= 2) {
            // Match
            ops[num_ops * 3] = 1;  // type: match
            ops[num_ops * 3 + 1] = offset - 1;
            ops[num_ops * 3 + 2] = length - 1;
            pos += length;
        } else {
            // Literal
            ops[num_ops * 3] = 0;  // type: literal
            int char_val = (int)data[pos];
            if (char_val > 127) char_val -= 256;
            ops[num_ops * 3 + 1] = char_val;
            pos++;
        }
        num_ops++;
    }

    // Encode
    memset(cc, 0, sizeof(cc));
    put_integer(num_ops, 9, 0);

    for (i = 0; i < num_ops; i++) {
        if (ops[i * 3] == 1) {
            // Match
            put_bit(1, 1);
            put_integer(ops[i * 3 + 1], 5, 2);
            put_integer(ops[i * 3 + 2], 2, 3);
        } else {
            // Literal
            put_bit(0, 1);
            int val = ops[i * 3 + 1];
            if (val >= 0) {
                put_bit(0, 8);  // positive
            } else {
                put_bit(1, 8);  // negative
                val = -val;
            }
            put_integer(val, 4, 9);
        }
    }

    flush_encoder();

    // Write output
    FILE *out = fopen("/app/data.comp", "wb");
    fwrite(output_buf, 1, output_pos, out);
    fclose(out);

    fprintf(stderr, "Compressed size: %d bytes\n", output_pos);
    fprintf(stderr, "Original size: %ld bytes\n", file_size);
    fprintf(stderr, "Number of operations: %d\n", num_ops);

    free(data);
    free(ops);
    return 0;
}

