#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int radix = 255;
long range_val = 1;
long low_val = 0;
int cc[200000];

unsigned char output_buf[100000];
int output_pos = 0;

void emit_byte(int b) {
    output_buf[output_pos++] = (unsigned char)b;
}

void put_bit(int bit, int ctx) {
    // Emit bytes if range gets too small - MATCH DECODER
    while (range_val < radix) {
        int byte_to_emit = (low_val / range_val) % radix + 1;
        emit_byte(byte_to_emit);
        low_val = low_val % range_val;
        low_val *= radix;
        range_val *= radix;
    }

    // Adaptive arithmetic coding - MATCH DECODER EXACTLY
    int *counts = cc + ctx * 2;
    // Decoder: split = range * -~*counts / (*counts + counts[1] + 2)
    // -~*counts is *counts + 1
    long split = range_val * (counts[0] + 1) / (counts[0] + counts[1] + 2);

    if (bit) {
        low_val += split;
        range_val -= split;
        counts[1]++;
    } else {
        range_val = split;
        counts[0]++;
    }
}

void put_integer(int val, int tmp, int ctx) {
    // CRITICAL: Decoder does ctx *= 99
    ctx *= 99;

    // Add offset that decoder will subtract
    int subtract_it = 1 << tmp;
    val += subtract_it;

    // Calculate number of bits needed
    int nbits = 0;
    int temp_val = val;
    while (temp_val > 0) {
        nbits++;
        temp_val >>= 1;
    }

    // Unary prefix: nbits-1 zeros, then a 1
    // Decoder: while (!get_bit(++tmp+ctx));
    int prefix_bits = nbits - 1;
    for (int i = 0; i < prefix_bits; i++) {
        tmp++;
        put_bit(0, tmp + ctx);  // Use tmp+ctx for prefix
    }
    tmp++;
    put_bit(1, tmp + ctx);  // Terminating 1

    // Binary value: nbits bits
    // Decoder: result_ans = result_ans*2 | get_bit(ctx);
    for (int i = nbits - 1; i >= 0; i--) {
        int bit = (val >> i) & 1;
        put_bit(bit, ctx);  // Use ctx (not tmp+ctx) for value bits
    }
}

void flush_encoder() {
    // Emit remaining state
    while (range_val < (1L << 30)) {
        int byte_to_emit = (low_val / range_val) % radix + 1;
        emit_byte(byte_to_emit);
        low_val = low_val % range_val;
        low_val *= radix;
        range_val *= radix;
    }
}

int main() {
    const char *test_str = "ABC";
