#include <string.h>

int radix = 255;
long range_val = 1;
long low_val = 0;
int cc[200000];

unsigned char output_buf[100000];
int output_pos = 0;

void emit_byte(int b) {
    output_buf[output_pos++] = (unsigned char)b;
    fprintf(stderr, "  emit_byte: %d (output_pos=%d)\n", b, output_pos);
}

void put_bit(int bit, int ctx) {
    fprintf(stderr, "put_bit(%d, ctx=%d) range=%ld, low=%ld\n", bit, ctx, range_val, low_val);

    // Emit bytes if range gets too small - MATCH DECODER
    while (range_val < radix) {
        int byte_to_emit = (low_val / range_val) % radix + 1;
        emit_byte(byte_to_emit);
        low_val = low_val % range_val;
        low_val *= radix;
        range_val *= radix;
        fprintf(stderr, "  after normalization: range=%ld, low=%ld\n", range_val, low_val);
    }

    // Adaptive arithmetic coding - MATCH DECODER EXACTLY
    int *counts = cc + ctx * 2;
    // Decoder: split = range * -~*counts / (*counts + counts[1] + 2)
    // -~*counts is *counts + 1
    long split = range_val * (counts[0] + 1) / (counts[0] + counts[1] + 2);

    fprintf(stderr, "  split=%ld, count0=%d, count1=%d\n", split, counts[0], counts[1]);

    if (bit) {
        low_val += split;
        range_val -= split;
        counts[1]++;
        fprintf(stderr, "  bit=1: new range=%ld, low=%ld\n", range_val, low_val);
    } else {
        range_val = split;
        counts[0]++;
        fprintf(stderr, "  bit=0: new range=%ld, low=%ld\n", range_val, low_val);
    }
}

void put_integer(int val, int tmp, int ctx) {
    fprintf(stderr, "\nput_integer(val=%d, tmp=%d, ctx=%d)\n", val, tmp, ctx);

    // CRITICAL: Decoder does ctx *= 99
    ctx *= 99;
    fprintf(stderr, "  ctx*=99 -> ctx=%d\n", ctx);

    // Add offset that decoder will subtract
    int subtract_it = 1 << tmp;
    val += subtract_it;
    fprintf(stderr, "  val + subtract_it(%d) = %d\n", subtract_it, val);

    // Calculate number of bits needed
    int nbits = 0;
    int temp_val = val;
    while (temp_val > 0) {
        nbits++;
        temp_val >>= 1;
    }
    fprintf(stderr, "  nbits=%d\n", nbits);

    // Unary prefix: nbits-1 zeros, then a 1
    // Decoder: while (!get_bit(++tmp+ctx));
    int prefix_bits = nbits - 1;
    fprintf(stderr, "  Emitting %d prefix zeros:\n", prefix_bits);
    for (int i = 0; i < prefix_bits; i++) {
        tmp++;
        fprintf(stderr, "  Prefix bit %d (ctx=%d):\n", i, tmp+ctx);
        put_bit(0, tmp + ctx);  // Use tmp+ctx for prefix
    }
    tmp++;
    fprintf(stderr, "  Terminating 1 (ctx=%d):\n", tmp+ctx);
    put_bit(1, tmp + ctx);  // Terminating 1

    // Binary value: nbits bits
    // Decoder: result_ans = result_ans*2 | get_bit(ctx);
    fprintf(stderr, "  Emitting %d value bits (ctx=%d):\n", nbits, ctx);
    for (int i = nbits - 1; i >= 0; i--) {
        int bit = (val >> i) & 1;
        fprintf(stderr, "    Value bit %d: %d\n", nbits-1-i, bit);
        put_bit(bit, ctx);  // Use ctx (not tmp+ctx) for value bits
    }
}

void flush_encoder() {
    fprintf(stderr, "\nflushing encoder...\n");
    // Emit remaining state
    while (range_val < (1L << 30)) {
        int byte_to_emit = (low_val / range_val) % radix + 1;
        emit_byte(byte_to_emit);
        low_val = low_val % range_val;
        low_val *= radix;
        range_val *= radix;
    }
    fprintf(stderr, "flush complete. Final range=%ld, low=%ld\n", range_val, low_val);
}

int main() {
    const char *test_str = "ABC";
    int len = strlen(test_str);

    fprintf(stderr, "=== ENCODING TEST: '%s' (length %d) ===\n\n", test_str, len);

    // Encode number of operations
    put_integer(len, 9, 0);  // INTOFF=9, ctx=0

    // Encode each character as a literal
    for (int i = 0; i < len; i++) {
        fprintf(stderr, "\n=== Op %d: literal '%c' (ASCII %d) ===\n", i, test_str[i], (int)test_str[i]);

        // Not a match
        fprintf(stderr, "Match bit:\n");
        put_bit(0, 1);

        // Sign bit (0 = positive)
        fprintf(stderr, "Sign bit:\n");
        put_bit(0, 8);

        // Character value
        put_integer((int)test_str[i], 4, 9);  // LITSIZE=4, ctx=9
    }

    flush_encoder();

    // Write output
    FILE *out = fopen("/app/test.comp", "wb");
    if (!out) {
        fprintf(stderr, "ERROR: Failed to open /app/test.comp for writing\n");
        return 1;
    }

    fwrite(output_buf, 1, output_pos, out);
    fclose(out);

    fprintf(stderr, "\n=== ENCODING COMPLETE ===\n");
    fprintf(stderr, "Total compressed size: %d bytes\n", output_pos);
    fprintf(stderr, "Bytes: ");
    for (int i = 0; i < output_pos; i++) {
        fprintf(stderr, "%d ", output_buf[i]);
    }
    fprintf(stderr, "\n");

    return 0;
}

