cat > /tmp/test_first_int.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>

#define radix 113
#define W for (i=0;i<tmp;i++)

int low = 0, range = 1;
int cc[100000];

int input_byte() {
  int b = getchar();
  if (b == EOF) {
    fprintf(stderr, "ERROR: Unexpected EOF\n");
    exit(1);
  }
  return b - 1;
}

int get_bit(int ctx) {
  while (range < radix) {
    low = low * radix + input_byte();
    range *= radix;
  }

  int* counts = cc + ctx * 2;
  long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);
  int the_bit = (low >= split);

  if (the_bit) {
    low -= split;
    range -= split;
  } else {
    range = split;
  }

  counts[the_bit]++;
  return the_bit;
}

int get_integer(int tmp, int ctx) {
  int subtract_it = 1<<tmp;
  int result_ans = 1;
  int i;
  ctx*=99;

  fprintf(stderr, "get_integer: initial tmp=%d, ctx=%d, subtract_it=%d\n", tmp, ctx, subtract_it);

  int prefix_count = 0;
  while (!get_bit(++tmp+ctx)) {
    prefix_count++;
    fprintf(stderr, "  Prefix iteration %d: tmp=%d\n", prefix_count, tmp);
  }
  fprintf(stderr, "  Got terminating 1 at tmp=%d, total prefix iterations=%d\n", tmp, prefix_count);

  tmp--;
  fprintf(stderr, "  After tmp--: tmp=%d, reading %d value bits from ctx=%d\n", tmp, tmp, ctx);

  W {
    result_ans = result_ans*2 | get_bit(ctx);
  }

  int final_value = result_ans - subtract_it;
  fprintf(stderr, "  result_ans=%d, final_value=%d\n", result_ans, final_value);

  return final_value;
}

int main() {
  fprintf(stderr, "Starting decoder test...\n");
  int j = get_integer(9, 0);
  fprintf(stderr, "\nFinal j value: %d\n", j);
  return 0;
}
EOF

