cat > /tmp/debug_ops.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>

#define radix 113
#define W for (i=0;i<tmp;i++)
#define OFF1 5
#define OFF2 2
#define LITSIZE 4

int low = 0, range = 1;
int cc[100000];

int input_byte() {
  int b = getchar();
  if (b == EOF) {
    fprintf(stderr, "ERROR: Unexpected EOF\n");
    exit(1);
  }
  return b - 1;
}

int get_bit(int ctx) {
  while (range < radix) {
    low = low * radix + input_byte();
    range *= radix;
  }

  int *counts = &cc[ctx * 2];
  int split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);

  int the_bit;
  if (low < split) {
    the_bit = 0;
    range = split;
  } else {
    the_bit = 1;
    low -= split;
    range -= split;
  }

  counts[the_bit]++;
  return the_bit;
}

int get_integer(int tmp, int ctx) {
  int subtract_it = 1<<tmp;
  int result_ans = 1;
  int i;
  ctx*=99;

  fprintf(stderr, "  get_integer(tmp=%d, ctx=%d): ", tmp, ctx/99);

  int prefix_count = 0;
  while (!get_bit(++tmp+ctx)) {
    prefix_count++;
  }
  fprintf(stderr, "prefix=%d, ", prefix_count);

  tmp--;
  fprintf(stderr, "reading %d value bits... ", tmp);

  W {
    result_ans = result_ans*2 | get_bit(ctx);
  }

  int final_value = result_ans - subtract_it;
  fprintf(stderr, "value=%d\n", final_value);

  return final_value;
}

int main() {
  int i, j = get_integer(9, 0);
  char buf[10000];
  char* Q = buf;

  fprintf(stderr, "\nOperation count j=%d\n\n", j);

  int op_num = 0;
  while (j-- && op_num < 5) {  // Only process first 5 operations for debug
    fprintf(stderr, "Operation %d: ", op_num);

    int is_match = get_bit(1);
    fprintf(stderr, "is_match=%d\n", is_match);

    if (is_match) {
      fprintf(stderr, "  MATCH: ");
      int offset = get_integer(OFF1, 2);
      fprintf(stderr, "offset=%d, ", offset);
      int len = get_integer(OFF2, 3);
      fprintf(stderr, "len=%d\n", len);

      char* z = Q - offset - 1;
      int tmp = len + 1;
      W {
        *Q++ = *z++;
      }
    } else {
      fprintf(stderr, "  LITERAL: ");
      int sign_bit = get_bit(8);
      fprintf(stderr, "sign=%d, ", sign_bit);
      int val = get_integer(LITSIZE, 9);
      fprintf(stderr, "val=%d, ", val);
      int char_val = (1 - 2*sign_bit) * val;
      fprintf(stderr, "char_val=%d\n", char_val);
      *Q++ = char_val;
    }

    op_num++;
  }

  fprintf(stderr, "\nProcessed %d operations, output length=%ld\n", op_num, Q - buf);
  fprintf(stderr, "Output: ");
  for (int k = 0; k < Q - buf && k < 50; k++) {
    fprintf(stderr, "%c", buf[k]);
  }
  fprintf(stderr, "\n");

  return 0;
}
EOF

