#!/usr/bin/perl
use strict;
use warnings;

# Simple encoder - LITERALS ONLY (no LZ77 matches)
# This tests if arithmetic coding alone works correctly

my $radix = 255;
my $threshold = 1 << 30;

# Arithmetic coder state
my $low = 0;
my $range = 0xFFFFFFFF;  # Start with maximum range
my @output = ();
my @cc = (2, 2);  # Context counts, matching decoder's initial [2,2,...]

sub emit_byte {
    my ($byte) = @_;
    push @output, $byte;
}

sub put_bit {
    my ($bit, $ctx) = @_;

    # Ensure context array has enough elements
    while (scalar(@cc) <= $ctx) {
        push @cc, 2;
    }

    my $total = $cc[$ctx * 2] + $cc[$ctx * 2 + 1];
    my $split = int($range * $cc[$ctx * 2] / $total);

    if ($bit == 0) {
        $range = $split;
        $cc[$ctx * 2]++;
    } else {
        $low += $split;
        $range -= $split;
        $cc[$ctx * 2 + 1]++;
    }

    # Normalization
    while ($range < $radix) {
        my $bucket = int($low / $range);
        my $byte_to_emit = ($bucket % $radix) + 1;
        emit_byte($byte_to_emit);

        # CRITICAL: Match decoder's reconstruction
        $low = ($low - $bucket * $range) * $radix;
        $range *= $radix;
    }
}

sub put_integer {
    my ($value, $size_bits, $context_base) = @_;

    # Encode size (number of bits needed)
    my $bits_needed = 0;
    my $temp = $value;
    while ($temp > 0) {
        $bits_needed++;
        $temp = int($temp / 2);
    }

    # Encode size using unary coding
    for (my $i = 0; $i < $bits_needed; $i++) {
        put_bit(1, $context_base + $i);
    }
    if ($bits_needed < $size_bits) {
        put_bit(0, $context_base + $bits_needed);
    }

    # Encode value bits
    for (my $i = $bits_needed - 1; $i >= 0; $i--) {
        my $bit = ($value >> $i) & 1;
        put_bit($bit, $context_base + $size_bits + 1 + $i);
    }
}

sub flush_encoder {
    # Emit final bytes to ensure decoder can reconstruct
    for (my $i = 0; $i < 4; $i++) {
        my $byte_to_emit = (int($low / $range) % $radix) + 1;
        emit_byte($byte_to_emit);
        $low = ($low - int($low / $range) * $range) * $radix;
        $range *= $radix;
    }
}

# Read input
my $input_file = "/app/test_minimal.txt";
open(my $fh, '<', $input_file) or die "Cannot open $input_file: $!";
my $data = do { local $/; <$fh> };
close($fh);

print STDERR "Input: '$data' (" . length($data) . " bytes)\n";

# Build operations - LITERALS ONLY for now
my @ops = ();
for my $char (split //, $data) {
    my $val = ord($char);
    # Convert to signed if needed
    if ($val > 127) {
        $val -= 256;
    }
    push @ops, [0, $val];  # [type=0 (literal), value]
}

my $num_ops = scalar(@ops);
print STDERR "Number of operations: $num_ops\n";

# Encode
put_integer($num_ops, 9, 0);

for my $op (@ops) {
    my ($type, $val) = @$op;

    # Type bit: 0=literal
    put_bit(0, 1);

    # Literal: sign bit + absolute value
    if ($val >= 0) {
        put_bit(0, 8);  # positive
    } else {
        put_bit(1, 8);  # negative
        $val = -$val;
    }
    put_integer($val, 4, 9);
}

flush_encoder();

# Write output
my $output_file = "/app/data.comp";
open(my $out, '>', $output_file) or die "Cannot open $output_file: $!";
binmode($out);
print $out pack('C*', @output);
close($out);

print STDERR "Compressed size: " . scalar(@output) . " bytes\n";
print STDERR "Output written to $output_file\n";

