    my $split = int($range * ($counts0 + 1) / ($counts0 + $counts1 + 2));

    if ($split == 0 || $split >= $range) {
        print STDERR "ERROR at put_bit($bit, $ctx): range=$range, cc0=$counts0, cc1=$counts1, split=$split\n";
        print STDERR "This will cause range to collapse to zero!\n";
        print STDERR "Output bytes so far: " . scalar(@output) . "\n";
        exit(1);
    }

    if ($bit == 0) {
        $range = $split;
        $cc[$ctx * 2]++;
    } else {
        $low += $split;
        $range -= $split;
        $cc[$ctx * 2 + 1]++;
    }
}

