sub put_bit {
    my ($bit, $ctx) = @_;

    # Ensure context array has enough elements
    while (scalar(@cc) <= $ctx * 2 + 1) {
        push @cc, 0;  # Initialize to 0 to match decoder
    }

    # CRITICAL: Match decoder's formula exactly
    # Decoder: split = range * (counts[0]+1) / (counts[0] + counts[1] + 2)
    my $counts0 = $cc[$ctx * 2];
    my $counts1 = $cc[$ctx * 2 + 1];
    my $split = int($range * ($counts0 + 1) / ($counts0 + $counts1 + 2));

    if ($split == 0 || $split >= $range) {
        print STDERR "ERROR at put_bit($bit, $ctx): range=$range, cc0=$counts0, cc1=$counts1, split=$split\n";
        print STDERR "This will cause range to collapse to zero!\n";
        print STDERR "Output bytes so far: " . scalar(@output) . "\n";
        exit(1);
    }

    if ($bit == 0) {
        $range = $split;
        $cc[$ctx * 2]++;
    } else {
        $low += $split;
        $range -= $split;
        $cc[$ctx * 2 + 1]++;
    }

    # Normalization
    while ($range < $radix) {
        my $bucket = int($low / $range);
        my $byte_to_emit = ($bucket % $radix) + 1;
        emit_byte($byte_to_emit);

        # CRITICAL: Match decoder's reconstruction
        $low = ($low - $bucket * $range) * $radix;
        $range *= $radix;
    }
}

