        fprintf(stderr, "ERROR: Ran out of input bytes at byte %d\n", byte_pos);
        exit(1);
    }

    int bit = (input[byte_pos] >> (7 - bit_pos)) & 1;
    fprintf(stderr, "get_bit: byte[%d] bit[%d] = %d\n", byte_pos, bit_pos, bit);

    bit_pos++;
    if (bit_pos == 8) {
        bit_pos = 0;
        byte_pos++;
    }

    return bit;
}

int get_integer(int tmp, int ctx) {
    fprintf(stderr, "\n=== get_integer(%d, %d) START ===\n", tmp, ctx);

    int subtract_it = 1 << tmp;
    fprintf(stderr, "subtract_it = 1<<%d = %d\n", tmp, subtract_it);

    int result_ans = 1;
    ctx *= 99;
    fprintf(stderr, "ctx *= 99 → ctx = %d\n", ctx);

    fprintf(stderr, "Reading unary prefix (while loop):\n");
    int loop_count = 0;
