use strict;
use warnings;
use Math::BigInt;

# Use BigInt for large numbers
my $range = Math::BigInt->new('0x100000000');
my $low = Math::BigInt->new(0);
my $radix = 257;
my @cc;

for my $ctx (0..9999) {
    $cc[$ctx][0] = 0;
    $cc[$ctx][1] = 0;
}

my @output_bits;

sub emit_byte {
    my ($byte) = @_;
    for (my $i = 7; $i >= 0; $i--) {
        push @output_bits, ($byte >> $i) & 1;
    }
    printf "    EMIT BYTE: 0x%02x (bits: ", $byte;
    for (my $i = 7; $i >= 0; $i--) {
        print(($byte >> $i) & 1);
    }
    print ")\n";
}

sub normalize {
    while ($range < 0x1000000) {
        my $byte_to_emit = ($low->copy()->bdiv($range)->bmod($radix))->numify() + 1;
        emit_byte($byte_to_emit);
        $low = ($low - ($low->copy()->bdiv($range)->bmul($range)))->bmul($radix);
        $range = $range->copy()->bmul($radix);
    }
}

sub put_bit {
    my ($symbol, $ctx) = @_;

    print sprintf("\nput_bit(%d, %d) | range=0x%s low=0x%s\n", 
                  $symbol, $ctx, $range->as_hex() =~ s/^0x//r, $low->as_hex() =~ s/^0x//r);

    my $c0 = $cc[$ctx][0] + 1;
    my $c1 = $cc[$ctx][1] + 1;
    my $split = $range->copy()->bmul($c0)->bdiv($c0 + $c1);

    normalize();

    if ($symbol == 0) {
        $range = $split->copy();
        $cc[$ctx][0]++;
    } else {
        $low = $low->copy()->badd($split);
        $range = $range->copy()->bsub($split);
        $cc[$ctx][1]++;
    }

    normalize();
}

