print "  At fresh context 10: cc[0]=0, cc[1]=0\n";
print "  split = range * (0+1) / (0+1 + 0+1) = range * 1/2 = range/2\n";
print "  For symbol=1: low += split, range -= split\n";
print "  Result: low = range/2, range = range/2\n";
print "  Initial: range=0x100000000, so after: range=0x80000000, low=0x80000000\n";
print "  0x80000000 >= 0x1000000, so NO normalization, NO bytes emitted yet\n\n";

