for (my $i = 8; $i >= 0; $i--) {
    my $bit = ($value >> $i) & 1;
    print "  Bit position $i: value=$bit\n";
    print "    put_bit($bit, $context_base)\n";
}

print "\n=== KEY INSIGHT ===\n";
print "After terminator, range=0x80000000 (half of original)\n";
print "Each value bit at context 0 will further split the range\n";
print "The FIRST value bit that triggers normalization will emit bytes\n";
print "Value 11 has 7 leading zeros: 000001011\n";
print "These 7 put_bit(0, 0) calls will keep reducing range until normalization triggers\n\n";

print "Let me check when normalize triggers:\n";
