#include <stdio.h>
#include <stdlib.h>
#define W for (i=0;i<tmp;i++)

int i;
int radix = 255;
int fraction;
long range = 1;
int tmp;
int cc[1000000];

int OFF1 = 5;
int OFF2 = 2;
int INTOFF = 9;
int LITSIZE = 4;

void normalize() {
  while (range <= radix) {
    int c = getchar();
    if (c == EOF) {
      fprintf(stderr, "ERROR: Unexpected EOF during normalize! range=%ld\n", range);
      exit(1);
    }
    fraction = fraction * (radix + 1) + c;
    range *= radix + 1;
  }
}

int get_bit(int context) {
  int p = cc[context];
  int xmid = p + ((range - p) >> 1);
  int bit;

  if (fraction >= xmid) {
    bit = 1;
    range -= xmid;
    fraction -= xmid;
    cc[context] += (radix + 1 - p) >> 3;
  } else {
    bit = 0;
    range = xmid;
    cc[context] -= p >> 3;
  }

  normalize();
  return bit;
}

int get_integer(int tmp, int ctx) {
  fprintf(stderr, "TRACE get_integer: size_bits=%d, ctx=%d\n", tmp, ctx);
  int subtract_it = 1<<tmp;
  int result_ans = 1;
  ctx*=99;

  fprintf(stderr, "  Reading unary prefix from contexts starting at %d...\n", tmp+1+ctx);
  int zero_count = 0;
  while (!get_bit(++tmp+ctx)) {
    zero_count++;
  }
  fprintf(stderr, "  Read %d zeros, then terminator at context %d\n", zero_count, tmp+ctx);

  tmp--;
  fprintf(stderr, "  After tmp--, tmp=%d, reading %d value bits from context %d\n", tmp, tmp, ctx);

  W {
    result_ans = result_ans*2 | get_bit(ctx);
  }

  int final = result_ans - subtract_it;
  fprintf(stderr, "  result_ans=%d, subtract_it=%d, final result=%d\n", result_ans, subtract_it, final);
  return final;
}


int main() {
  fprintf(stderr, "=== Starting decompression ===\n");
  int tmp,i,j = get_integer(9, 0);
  fprintf(stderr, "Number of operations: %d\n\n", j);

  char* z;

  char buf[10000];
  char* Q = buf;

  int op_num = 0;
  while (j--) {
    fprintf(stderr, "Operation %d:\n", ++op_num);
    int type_bit = get_bit(1);
    fprintf(stderr, "  Type bit (context 1): %d\n", type_bit);

    if (type_bit) {
      z = Q - get_integer(OFF1, 2) - 1;
      tmp = get_integer(OFF2, 3) + 1;
        W {
          *Q++ = *z++;
        }
    } else {
      int sign_bit = get_bit(8);
      fprintf(stderr, "  Sign bit (context 8): %d\n", sign_bit);
      int value = get_integer(LITSIZE, 9);
      int final_value = (1-2*sign_bit) * value;
      fprintf(stderr, "  Value: %d, Final (with sign): %d, Char: '%c'\n", value, final_value, final_value);
      *Q++ = final_value;
    }
  }

  printf("%s", buf);
}
EOF

